html:
{%- from "iso_compliance/templates/includes/en10204.html" import styles, head, products, results, statement, sign -%}
{#- EN 10204 type 3.1: inspection certificate, results of specific inspection of the
    delivered batches; item groups that issue a material certificate add the
    supplier trace and material properties (mtc_row). -#}
{%- set d = en10204(doc, "3.1") -%}
{{ styles() }}
<div class="en">
{{ head(d) }}
{{ products(d) }}
{{ results(d) }}
{%- for r in d.rows if r.mtc %}
{%- set m = r.mtc %}
<div class="en-h">{{ r.item_code }} &middot; material traceability</div>
<table class="en-t"><thead><tr><th style="width:12%">Role</th><th style="width:18%">Material</th><th style="width:14%">Batch / heat</th><th style="width:22%">Supplier</th><th style="width:14%">Receipt</th><th>Supplier certificate</th></tr></thead><tbody>
{%- for s in m.sources %}<tr><td>{{ s.role }}</td><td>{{ s.item }}</td><td>{{ s.batch }}{% if s.heat_no %} / {{ s.heat_no }}{% endif %}</td>
	<td>{{ s.supplier or "&mdash;" }}</td><td>{{ s.receipt }}</td><td>{% if s.certificate %}{{ s.certificate_name }}{% else %}<span class="en-gap">not on file</span>{% endif %}</td></tr>
{%- else %}<tr><td colspan="6" class="en-gap">No receipt trace for this delivery.</td></tr>{%- endfor %}
</tbody></table>
{%- if m.properties %}
<div class="en-h">{{ r.item_code }} &middot; material properties</div>
<table class="en-t"><thead><tr><th>Property</th><th style="width:18%">Method</th><th style="width:20%">Requirement</th><th style="width:18%">Result</th><th style="width:12%">Source</th></tr></thead><tbody>
{%- for p in m.properties %}<tr><td>{{ p.property }}</td><td>{{ p.method or "&mdash;" }}</td><td>{{ p.limits }} {{ p.unit }}</td>
	<td class="{{ '' if p.ok else 'en-nok' }}">{{ p.result or "&mdash;" }} {{ p.unit if p.result }}</td><td>{{ p.source }}</td></tr>{%- endfor %}
</tbody></table>
{%- endif %}
{%- endfor %}
{{ statement(d, "We hereby certify that the products supplied are in compliance with the requirements of the order. The test results given are based on specific inspection of the products supplied.") }}
{{ sign(d, "Manufacturer's authorised inspection representative, independent of the manufacturing department") }}
</div>
